      - name: Verify bounded funding plan (no network, no payment)
        run: node --test scripts/tests/funding-plan.test.mjs
      - name: Install local-chain test dependencies only
        run: npm install --no-save ethers@6.17.0 solc@0.8.30 ganache@7.9.2
      - name: Verify financial invariants on local simulated chain
        run: node invest-channel/tests/funding.test.cjs

